useBindings(() => {
    return {
        target: inputTarget,
        enabled: (() => {
            cursorVersion();
            return inputTarget() !== undefined && !props.disabled && !auto()?.visible && input !== undefined;
        })(),
        commands: [
            {
                name: "prompt.history.previous",
                title: "Previous prompt history",
                category: "Prompt",
                run() {
                    if (input.cursorOffset !== 0) {
                        if (input.scrollY + input.visualCursor.visualRow === 0)
                            input.cursorOffset = 0;
                        return false;
                    }
                    const item = history.move(-1, input.plainText);
                    if (!item)
                        return false;
                    input.setText(item.input);
                    setStore("prompt", item);
                    setStore("mode", item.mode ?? "normal");
                    restoreExtmarksFromParts(item.parts);
                    input.cursorOffset = 0;
                },
            },
        ],
        bindings: tuiConfig.keybinds.get("prompt.history.previous"),
    };
})

useBindings(() => {
    return {
        target: inputTarget,
        enabled: (() => {
            cursorVersion();
            return inputTarget() !== undefined && !props.disabled && !auto()?.visible && input !== undefined;
        })(),
        commands: [
            {
                name: "prompt.history.next",
                title: "Next prompt history",
                category: "Prompt",
                run() {
                    if (input.cursorOffset !== input.plainText.length) {
                        if (input.scrollY + input.visualCursor.visualRow ===
                            Math.max(0, input.editorView.getTotalVirtualLineCount() - 1))
                            input.cursorOffset = input.plainText.length;
                        return false;
                    }
                    const item = history.move(1, input.plainText);
                    if (!item)
                        return false;
                    input.setText(item.input);
                    setStore("prompt", item);
                    setStore("mode", item.mode ?? "normal");
                    restoreExtmarksFromParts(item.parts);
                    input.cursorOffset = input.plainText.length;
                },
            },
        ],
        bindings: tuiConfig.keybinds.get("prompt.history.next"),
    };
})

handlers.code:
{(entry) => {
    input.setText(entry.input);
    setStore("prompt", { input: entry.input, parts: entry.parts });
    restoreExtmarksFromParts(entry.parts);
    input.gotoBufferEnd();
}}

{() => {
    const value = input.plainText;
    setStore("prompt", "input", value);
    auto()?.onInput(value);
    syncExtmarksWithPromptParts();
    setCursorVersion((value) => value + 1);
}}

{async (event: PasteEvent) => {
    if (props.disabled) {
        event.preventDefault();
        return;
    }
    const normalizedText = decodePasteBytes(event.bytes).replace(/\r\n/g, "\n").replace(/\r/g, "\n");
    const pastedContent = normalizedText.trim();
    if (!pastedContent) {
        keymap.dispatchCommand("prompt.paste");
        return;
    }
    event.preventDefault();
    await pasteInputText(normalizedText);
}}

