    ],
    bindings: [
        {
            key: "left",
            desc: "Previous permission option",
            group: "Permission",
            cmd: () => {
                const idx = keys.indexOf(store.selected);
                const next = keys[(idx - 1 + keys.length) % keys.length];
                setStore("selected", next);
            },
        },
        {
            key: "h",
            desc: "Previous permission option",
            group: "Permission",
            cmd: () => {
                const idx = keys.indexOf(store.selected);
                const next = keys[(idx - 1 + keys.length) % keys.length];
                setStore("selected", next);
            },
        },
        {
            key: "right",
            desc: "Next permission option",
            group: "Permission",
            cmd: () => {
                const idx = keys.indexOf(store.selected);
                const next = keys[(idx + 1) % keys.length];
                setStore("selected", next);
            },
