    });
}}

{(option) => {
    if (option === "always") {
        setStore("stage", "always");
        return;
    }
    if (option === "reject") {
        if (session()?.parentID) {
            setStore("stage", "reject");
            return;
        }
        void sdk.client.permission.reply({
            reply: "reject",
            requestID: props.request.id,
            directory: props.directory,
            workspace: project.workspace.current(),
        });
        return;
    }
    void sdk.client.permission.reply({
        reply: "once",
        requestID: props.request.id,
        directory: props.directory,
        workspace: project.workspace.current(),
    });
}}

