useBindings(() => {
    const visible = shownActions();
    return {
        commands: [
            {
                name: "dialog.select.prev",
                title: "Previous item",
                category: "Dialog",
                run() {
                    setStore("input", "keyboard");
                    move(-1);
                },
            },
            {
                name: "dialog.select.next",
                title: "Next item",
                category: "Dialog",
                run() {
                    setStore("input", "keyboard");
                    move(1);
                },
            },
            {
                name: "dialog.select.page_up",
                title: "Page up",
                category: "Dialog",
                run() {
                    setStore("input", "keyboard");
                    move(-10);
                },
            },
            {
                name: "dialog.select.page_down",
                title: "Page down",
                category: "Dialog",
                run() {
                    setStore("input", "keyboard");
                    move(10);
                },
            },
            {
                name: "dialog.select.home",
                title: "First item",
                category: "Dialog",
                run() {
                    if (props.locked)
                        return;
                    setStore("input", "keyboard");
                    moveTo(0);
                },
            },
            {
                name: "dialog.select.end",
                title: "Last item",
                category: "Dialog",
                run() {
                    if (props.locked)
                        return;
                    setStore("input", "keyboard");
                    moveTo(flat().length - 1);
                },
            },
            {
                name: "dialog.select.submit",
                title: "Select item",
                category: "Dialog",
                run: submit,
            },
            ...visible.map((item) => ({
                name: item.command,
                title: item.title,
                category: "Dialog",
                run() {
                    if (props.locked)
                        return;
                    if (isActionDisabled(item))
                        return;
                    setStore("input", "keyboard");
                    const option = selected();
                    if (!option)
                        return;
                    item.onTrigger(option);
                },
            })),
        ],
        bindings: [
            ...tuiConfig.keybinds.gather("dialog.select", [
                "dialog.select.prev",
                "dialog.select.next",
                "dialog.select.page_up",
                "dialog.select.page_down",
                "dialog.select.home",
                "dialog.select.end",
                "dialog.select.submit",
            ]),
            ...visible.flatMap((item) => tuiConfig.keybinds.get(item.command)),
            ...(visible.length
                ? [
                    {
                        key: "tab",
                        desc: "Next dialog action",
                        group: "Dialog",
                        cmd: () => moveAction(1),
                    },
                    {
                        key: "shift+tab",
                        desc: "Previous dialog action",
                        group: "Dialog",
                        cmd: () => moveAction(-1),
                    },
                ]
                : []),
            ...(props.bindings ?? []).filter((binding) => {
                if (typeof binding.cmd !== "string")
                    return true;
                return visible.some((item) => item.command === binding.cmd);
            }),
        ],
    };
})

