    enabled: store.stack.length > 0 && !renderer.getSelection()?.getSelectedText(),
    bindings: [
        {
            key: "escape",
            desc: "Close dialog",
            group: "Dialog",
            cmd: () => {
                if (renderer.getSelection()) {
                    renderer.clearSelection();
                }
                const current = store.stack.at(-1);
                current?.onClose?.();
                setStore("stack", store.stack.slice(0, -1));
                refocus();
            },
        },
        {
            key: "ctrl+c",
            desc: "Close dialog",
            group: "Dialog",
            cmd: () => {
                if (renderer.getSelection()) {
                    renderer.clearSelection();
                }
                const current = store.stack.at(-1);
                current?.onClose?.();
                setStore("stack", store.stack.slice(0, -1));
